package com.akto.service.scripts.validation;

import lombok.Getter;
import lombok.Setter;

/**
 * One Validate click, as the client sends it. For each phase at most one of javascript (a draft is
 * created from it) and scriptId (a library script) is set; neither means no script for that phase.
 */
@Getter
@Setter
public class ScriptValidationRequest {
    /** Generated by the client; draft ids derive from it, so a retried request reuses the same drafts. */
    private String validationId;
    private int apiCollectionId;
    private String url;
    private String method;
    private String preJavascript;
    private String preScriptId;
    private String postJavascript;
    private String postScriptId;
    /** hexId of a test role, or blank for none. */
    private String testRoleId;
    /** Blank = dashboard module (the only module today). */
    private String miniTestingName;
}
